SELECT CAST(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN admission.admittime AND (admission.admittime + INTERVAL '72 hours') THEN emar.emar_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN emar.charttime BETWEEN (admission.dischtime - INTERVAL '48 hours') AND admission.dischtime THEN emar.emar_id END), 0) AS ratio FROM admissions admission JOIN patients patient ON admission.subject_id = patient.subject_id JOIN emar ON admission.subject_id = emar.subject_id WHERE patient.gender = 'M' AND patient.anchor_age = 76 AND patient.anchor_year = 2017 AND patient.anchor_year_group = '71-81' AND emar.drug_type IN ('Metformin', 'Sulfonylurea', 'DPP-4', 'SGLT2', 'Thiazolidinedione');